create table if not exists public.school_departments (
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, name text not null, code text, head_membership_id uuid references public.school_memberships(id) on delete set null, is_active boolean not null default true, created_at timestamptz not null default now(), unique(school_id,name)
);
alter table public.subjects add column if not exists department_id uuid references public.school_departments(id) on delete set null;
create table if not exists public.grade_subjects (
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, grade_level_id uuid not null references public.grade_levels(id) on delete cascade, subject_id uuid not null references public.subjects(id) on delete cascade, is_compulsory boolean not null default true, created_at timestamptz not null default now(), unique(grade_level_id,subject_id)
);
create table if not exists public.subject_combinations (
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, grade_level_id uuid not null references public.grade_levels(id) on delete cascade, name text not null, code text, subject_ids uuid[] not null default '{}', selection_count smallint not null default 1 check(selection_count > 0), is_active boolean not null default true, created_at timestamptz not null default now(), unique(grade_level_id,name)
);
create table if not exists public.school_academic_policies (
 id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id) on delete cascade, grade_level_id uuid references public.grade_levels(id) on delete cascade, pass_mark numeric(5,2) not null default 40 check(pass_mark between 0 and 100), formative_weight numeric(5,2) not null default 20 check(formative_weight between 0 and 100), midterm_weight numeric(5,2) not null default 30 check(midterm_weight between 0 and 100), final_weight numeric(5,2) not null default 50 check(final_weight between 0 and 100), promotion_minimum_average numeric(5,2) not null default 40 check(promotion_minimum_average between 0 and 100), promotion_minimum_subjects integer not null default 0 check(promotion_minimum_subjects >= 0), require_core_subjects_pass boolean not null default false, core_subject_ids uuid[] not null default '{}', updated_at timestamptz not null default now(), check(formative_weight+midterm_weight+final_weight=100)
);
create unique index if not exists school_academic_policies_scope_uidx on public.school_academic_policies(school_id,coalesce(grade_level_id,'00000000-0000-0000-0000-000000000000'::uuid));
alter table public.school_departments enable row level security; alter table public.grade_subjects enable row level security; alter table public.subject_combinations enable row level security; alter table public.school_academic_policies enable row level security;
drop policy if exists school_departments_select on public.school_departments; create policy school_departments_select on public.school_departments for select using (private.is_school_member(school_id));
drop policy if exists school_departments_manage on public.school_departments; create policy school_departments_manage on public.school_departments for all using (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[])) with check (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[]));
drop policy if exists grade_subjects_select on public.grade_subjects; create policy grade_subjects_select on public.grade_subjects for select using (private.is_school_member(school_id));
drop policy if exists grade_subjects_manage on public.grade_subjects; create policy grade_subjects_manage on public.grade_subjects for all using (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[])) with check (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[]));
drop policy if exists subject_combinations_select on public.subject_combinations; create policy subject_combinations_select on public.subject_combinations for select using (private.is_school_member(school_id));
drop policy if exists subject_combinations_manage on public.subject_combinations; create policy subject_combinations_manage on public.subject_combinations for all using (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[])) with check (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[]));
drop policy if exists school_academic_policies_select on public.school_academic_policies; create policy school_academic_policies_select on public.school_academic_policies for select using (private.is_school_member(school_id));
drop policy if exists school_academic_policies_manage on public.school_academic_policies; create policy school_academic_policies_manage on public.school_academic_policies for all using (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[])) with check (private.has_school_role(school_id,array['owner','school_admin','headteacher']::text[]));
